```tsx
// CheckoutPage.tsx
import React, { useState } from 'react';
import './CheckoutPage.css';

export interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
  imageUrl?: string;
}

export interface DeliveryAddress {
  fullName: string;
  street: string;
  city: string;
  postalCode: string;
  country: string;
  phone: string;
}

interface CheckoutPageProps {
  items: CartItem[];
  onBackToCart: () => void;
  onPay: (address: DeliveryAddress) => void;
  isSubmitting?: boolean;
}

const SHIPPING_COST = 4.99;

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  street: '',
  city: '',
  postalCode: '',
  country: '',
  phone: '',
};

type FormErrors = Partial<Record<keyof DeliveryAddress, string>>;

function formatPrice(value: number): string {
  return `$${value.toFixed(2)}`;
}

function validateAddress(address: DeliveryAddress): FormErrors {
  const errors: FormErrors = {};

  if (!address.fullName.trim()) errors.fullName = 'Full name is required';
  if (!address.street.trim()) errors.street = 'Street address is required';
  if (!address.city.trim()) errors.city = 'City is required';
  if (!address.postalCode.trim()) errors.postalCode = 'Postal code is required';
  if (!address.country.trim()) errors.country = 'Country is required';
  if (!address.phone.trim()) {
    errors.phone = 'Phone number is required';
  } else if (!/^[+\d][\d\s-]{6,}$/.test(address.phone.trim())) {
    errors.phone = 'Enter a valid phone number';
  }

  return errors;
}

export default function CheckoutPage({
  items,
  onBackToCart,
  onPay,
  isSubmitting = false,
}: CheckoutPageProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<FormErrors>({});

  const subtotal = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const shipping = items.length > 0 ? SHIPPING_COST : 0;
  const total = subtotal + shipping;

  function handleFieldChange(field: keyof DeliveryAddress, value: string) {
    setAddress((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  }

  function handleSubmit(event: React.FormEvent) {
    event.preventDefault();

    const validationErrors = validateAddress(address);
    setErrors(validationErrors);

    if (Object.keys(validationErrors).length === 0) {
      onPay(address);
    }
  }

  return (
    <div className="checkout-page">
      <div className="checkout-header">
        <button
          type="button"
          className="back-link"
          onClick={onBackToCart}
          aria-label="Back to cart"
        >
          &larr; Back to cart
        </button>
        <h1>Checkout</h1>
      </div>

      <div className="checkout-layout">
        <section className="checkout-section cart-summary" aria-labelledby="cart-summary-heading">
          <h2 id="cart-summary-heading">Your order</h2>

          {items.length === 0 ? (
            <p className="empty-cart-message">Your cart is empty.</p>
          ) : (
            <ul className="cart-item-list">
              {items.map((item) => (
                <li key={item.id} className="cart-item">
                  <div className="cart-item-image">
                    {item.imageUrl ? (
                      <img src={item.imageUrl} alt={item.name} />
                    ) : (
                      <div className="cart-item-image-placeholder" aria-hidden="true" />
                    )}
                  </div>

                  <div className="cart-item-details">
                    <span className="cart-item-name">{item.name}</span>
                    <span className="cart-item-qty">Qty: {item.quantity}</span>
                  </div>

                  <span className="cart-item-price">
                    {formatPrice(item.price * item.quantity)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <div className="totals">
            <div className="totals-row">
              <span>Subtotal</span>
              <span>{formatPrice(subtotal)}</span>
            </div>
            <div className="totals-row">
              <span>Shipping</span>
              <span>{formatPrice(shipping)}</span>
            </div>
            <div className="totals-row totals-row-final">
              <span>Total</span>
              <span>{formatPrice(total)}</span>
            </div>
          </div>
        </section>

        <section className="checkout-section address-form" aria-labelledby="address-heading">
          <h2 id="address-heading">Delivery address</h2>

          <form onSubmit={handleSubmit} noValidate>
            <div className="form-field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                value={address.fullName}
                onChange={(e) => handleFieldChange('fullName', e.target.value)}
                aria-invalid={Boolean(errors.fullName)}
                aria-describedby={errors.fullName ? 'fullName-error' : undefined}
              />
              {errors.fullName && (
                <span id="fullName-error" className="field-error">
                  {errors.fullName}
                </span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="street">Street address</label>
              <input
                id="street"
                type="text"
                value={address.street}
                onChange={(e) => handleFieldChange('street', e.target.value)}
                aria-invalid={Boolean(errors.street)}
                aria-describedby={errors.street ? 'street-error' : undefined}
              />
              {errors.street && (
                <span id="street-error" className="field-error">
                  {errors.street}
                </span>
              )}
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  value={address.city}
                  onChange={(e) => handleFieldChange('city', e.target.value)}
                  aria-invalid={Boolean(errors.city)}
                  aria-describedby={errors.city ? 'city-error' : undefined}
                />
                {errors.city && (
                  <span id="city-error" className="field-error">
                    {errors.city}
                  </span>
                )}
              </div>

              <div className="form-field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  value={address.postalCode}
                  onChange={(e) => handleFieldChange('postalCode', e.target.value)}
                  aria-invalid={Boolean(errors.postalCode)}
                  aria-describedby={errors.postalCode ? 'postalCode-error' : undefined}
                />
                {errors.postalCode && (
                  <span id="postalCode-error" className="field-error">
                    {errors.postalCode}
                  </span>
                )}
              </div>
            </div>

            <div className="form-field">
              <label htmlFor="country">Country</label>
              <input
                id="country"
                type="text"
                value={address.country}
                onChange={(e) => handleFieldChange('country', e.target.value)}
                aria-invalid={Boolean(errors.country)}
                aria-describedby={errors.country ? 'country-error' : undefined}
              />
              {errors.country && (
                <span id="country-error" className="field-error">
                  {errors.country}
                </span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="phone">Phone number</label>
              <input
                id="phone"
                type="tel"
                value={address.phone}
                onChange={(e) => handleFieldChange('phone', e.target.value)}
                aria-invalid={Boolean(errors.phone)}
                aria-describedby={errors.phone ? 'phone-error' : undefined}
              />
              {errors.phone && (
                <span id="phone-error" className="field-error">
                  {errors.phone}
                </span>
              )}
            </div>

            <div className="checkout-actions">
              <button
                type="button"
                className="btn btn-secondary"
                onClick={onBackToCart}
                disabled={isSubmitting}
              >
                Back to cart
              </button>
              <button
                type="submit"
                className="btn btn-primary"
                disabled={items.length === 0 || isSubmitting}
              >
                {isSubmitting ? 'Processing…' : `Pay ${formatPrice(total)}`}
              </button>
            </div>
          </form>
        </section>
      </div>
    </div>
  );
}
