import CheckoutPage, { CartItem, DeliveryAddress } from './CheckoutPage';

const cartItems: CartItem[] = [
  { id: '1', name: 'Wireless Headphones', price: 79.99, quantity: 1 },
  { id: '2', name: 'Phone Case', price: 14.5, quantity: 2 },
];

function App() {
  function handlePay(address: DeliveryAddress) {
    console.log('Paying with address:', address);
  }

  function handleBackToCart() {
    console.log('Navigate back to cart');
  }

  return (
    <CheckoutPage items={cartItems} onBackToCart={handleBackToCart} onPay={handlePay} />
  );
}

export default App;
```

Notes:
- `onPay` and `onBackToCart` are callbacks you wire up to your routing/payment logic; the component itself only validates the address and computes totals.
- Pay button disables when the cart is empty or `isSubmitting` is true (pass that prop while your payment call is in flight).
- Responsive: two-column layout collapses to one column under 720px.
